// ── IndexedDB storage layer ───────────────────────────────────────────────
const DB_NAME = "beemark";
const DB_VER  = 1;
const STORE   = "kv";

function openDB() {
  return new Promise((resolve, reject) => {
    const req = indexedDB.open(DB_NAME, DB_VER);
    req.onupgradeneeded = e => e.target.result.createObjectStore(STORE);
    req.onsuccess = e => resolve(e.target.result);
    req.onerror   = e => reject(e.target.error);
  });
}

async function idbGet(key, def) {
  try {
    const db = await openDB();
    return await new Promise((resolve, reject) => {
      const tx  = db.transaction(STORE, "readonly");
      const req = tx.objectStore(STORE).get(key);
      req.onsuccess = () => resolve(req.result !== undefined ? req.result : def);
      req.onerror   = () => resolve(def);
    });
  } catch { return def; }
}

async function idbSet(key, val) {
  try {
    const db = await openDB();
    await new Promise((resolve, reject) => {
      const tx  = db.transaction(STORE, "readwrite");
      const req = tx.objectStore(STORE).put(val, key);
      req.onsuccess = () => resolve();
      req.onerror   = () => reject(req.error);
    });
  } catch {}
}

// One-time migration: copy any existing localStorage data into IDB
async function migrateFromLocalStorage() {
  const migKey = "bm_idb_migrated";
  if (localStorage.getItem(migKey)) return;
  const keys = ["bm_hives3","bm_apiaries3","bm_activeApiary3","bm_equip_manual"];
  for (const k of keys) {
    try {
      const raw = localStorage.getItem(k);
      if (raw !== null) await idbSet(k, JSON.parse(raw));
    } catch {}
  }
  localStorage.setItem(migKey, "1");
}


// ── PNG icon badges ────────────────────────────────────────────────────────
// All icons sit in a fixed 22px tall container but are scaled so the VISIBLE
// graphic occupies the same optical height regardless of canvas padding in the PNG.
// Crown  → 22px (fills canvas well)
// Warning→ 22px (triangle fills canvas well — was visually small before, needs to be bigger)
// Cross  → 17px (circle is large relative to canvas, needs to be smaller)
// ActCog → 20px (fills canvas reasonably)
const BADGE_H = 22; // container height in px — same for all
const DEWBERRY_B64  = "data:image/png;base64,";
const BADGE_SIZES = { crown:22, warning:22, cross:17, actcog:20, pen:17 };
const BADGE_FILTERS = { pen:"invert(33%) sepia(90%) saturate(400%) hue-rotate(240deg) brightness(0.75)" };
const BadgeImg = ({ src, alt, name }) => {
  const w = BADGE_SIZES[name] || BADGE_H;
  const filter = BADGE_FILTERS[name] || undefined;
  return (
    <img src={src} alt={alt} style={{ width:w, height:w, objectFit:"contain", display:"block", filter, flexShrink:0 }}/>
  );
};

// showTreatmentActive=true → cross shows only when active treatment exists (for hive list)
const InspectionBadges = ({ ins, treatments=[], showTreatmentActive=false }) => {
  const showCrown   = ins?.queen_seen==="yes";
  const showWarning = ins?.queen_cells==="yes";
  const showCross   = showTreatmentActive
    ? treatments.some(t=>!t.complete && treatmentDaysLeft(t)!==null)
    : ins?.has_treatment==="yes";
  const showCog     = ins?.has_action==="yes";
  if(!showCrown && !showWarning && !showCross && !showCog) return null;
  return (
    <div style={{ display:"flex",gap:2,alignItems:"center" }}>
      {showCrown   && <BadgeImg src={CROWN_B64}   alt="Queen seen"   name="crown"/>}
      {showWarning && <BadgeImg src={WARNING_B64} alt="Queen cells"  name="warning"/>}
      {showCross   && <BadgeImg src={CROSS_B64}   alt="Treatment"    name="cross"/>}
      {showCog     && <BadgeImg src={ACTCOG_B64}  alt="Action"       name="actcog"/>}
    </div>
  );
};

// Crown-only badge — sits inline after hive name, bottom-aligned with text
// Uses a slightly smaller rendered size and baseline alignment
const CrownBadge = ({ ins }) => {
  if(ins?.queen_seen!=="yes") return null;
  return (
    <span style={{ display:"inline-flex",alignItems:"flex-end",flexShrink:0,lineHeight:1 }}>
      <img src={CROWN_B64} alt="Queen seen" style={{ width:17,height:17,objectFit:"contain",display:"block",marginBottom:1 }}/>
    </span>
  );
};

// Non-crown badges (warning, cross, cog) — for right side placement
const NonCrownBadges = ({ ins, treatments=[], showTreatmentActive=false }) => {
  const showWarning = ins?.queen_cells==="yes";
  const showCross   = showTreatmentActive
    ? treatments.some(t=>!t.complete && treatmentDaysLeft(t)!==null)
    : ins?.has_treatment==="yes";
  const showCog     = ins?.has_action==="yes";
  if(!showWarning && !showCross && !showCog) return null;
  return (
    <div style={{ display:"flex",gap:2,alignItems:"center" }}>
      {showWarning && <BadgeImg src={WARNING_B64} alt="Queen cells" name="warning"/>}
      {showCross   && <BadgeImg src={CROSS_B64}   alt="Treatment"   name="cross"/>}
      {showCog     && <BadgeImg src={ACTCOG_B64}  alt="Action"      name="actcog"/>}
    </div>
  );
};


