const NAV_ACTIVE_FILTER   = "invert(63%) sepia(54%) saturate(410%) hue-rotate(116deg) brightness(90%) contrast(90%)";
const NAV_INACTIVE_FILTER = "invert(70%) sepia(10%) saturate(300%) hue-rotate(120deg) brightness(95%) contrast(85%)";

const NavIcon = ({ name, isActive, size=26 }) => {
  const src = NAV_ICONS[name];
  if(!src) return <Icon name="hive" size={size} color={isActive?C.primary:C.textMuted}/>;
  return (
    <img src={src} alt={name} style={{
      width:size, height:size, objectFit:"contain", display:"block",
      filter: isActive ? NAV_ACTIVE_FILTER : NAV_INACTIVE_FILTER,
      opacity: isActive ? 1 : 0.6,
    }}/>
  );
};

