const Btn = ({ children, onClick, variant="primary", small, style={}, disabled }) => {
  const base = { border:"none",borderRadius:10,cursor:disabled?"not-allowed":"pointer",fontFamily:"'Roboto',sans-serif",fontWeight:500,display:"inline-flex",alignItems:"center",gap:6,transition:"all .15s",opacity:disabled?.5:1,padding:small?"8px 14px":"13px 22px",fontSize:small?15:16 };
  const variants = {
    primary:{ background:`linear-gradient(135deg,${C.primary},${C.primaryDark})`,color:"#fff",boxShadow:`0 3px 12px rgba(${hexToRgb(C.primary)},.4)` },
    ghost:  { background:"#fff",color:C.textSecondary,border:`1.5px solid ${C.border}`,boxShadow:"0 1px 4px rgba(0,0,0,.06)" },
    danger: { background:`rgba(${hexToRgb(C.red)},.08)`,color:C.red,border:`1.5px solid rgba(${hexToRgb(C.red)},.25)` },
    warning:{ background:`rgba(${hexToRgb(C.orange)},.08)`,color:C.orange,border:`1.5px solid rgba(${hexToRgb(C.orange)},.25)` },
  };
  return <button onClick={disabled?undefined:onClick} style={{...base,...(variants[variant]||variants.primary),...style}}>{children}</button>;
};
