const SectionHead = ({ label }) => (
  <div style={{ fontWeight:700,color:C.textPrimary,fontSize:16,marginBottom:14,paddingBottom:8,borderBottom:`1px solid ${C.border}` }}>{label}</div>
);
const HexBg = ({ opacity=0.045 }) => (
  <svg style={{ position:"fixed",top:0,left:0,width:"100%",height:"100%",opacity,pointerEvents:"none",zIndex:0 }} xmlns="http://www.w3.org/2000/svg">
    <defs><pattern id="hex" x="0" y="0" width="60" height="52" patternUnits="userSpaceOnUse">
      <polygon points="30,2 58,17 58,47 30,62 2,47 2,17" fill="none" stroke={C.primary} strokeWidth="1.5"/>
    </pattern></defs>
    <rect width="100%" height="100%" fill="url(#hex)"/>
  </svg>
);
const PageWrap = ({ children, style={} }) => (
  <div style={{ minHeight:"100vh",background:`linear-gradient(160deg,${C.primaryLight} 0%,${C.bg} 35%,${C.surface} 100%)`,...style }}>
    <HexBg/><div style={{ position:"relative",zIndex:1,paddingBottom:88 }}>{children}</div>
  </div>
);
const PageHeader = ({ title, subtitle, onBack, rightSlot }) => (
  <div style={{ padding:"14px 16px",background:"rgba(255,255,255,.88)",backdropFilter:"blur(16px)",borderBottom:`1px solid ${C.border}`,display:"flex",alignItems:"center",gap:12,position:"sticky",top:0,zIndex:50 }}>
    {onBack&&<button onClick={onBack} style={{ background:"none",border:"none",cursor:"pointer",padding:4,flexShrink:0,display:"flex" }}><Icon name="back" color={C.textSecondary} size={24}/></button>}
    <div style={{ flex:1,minWidth:0 }}>
      <div style={{ fontSize:19,fontWeight:700,color:C.textPrimary,lineHeight:1.2 }}>{title}</div>
      {subtitle&&<div style={{ fontSize:13,color:C.textMuted,marginTop:1 }}>{subtitle}</div>}
    </div>
    {rightSlot}
  </div>
);

// Reusable cog dropdown menu
// Items: { label, icon, onClick } | { label, icon, isFileInput, onFileChange } | "divider"
const CogMenu = ({ items, buttonStyle={}, iconColor=C.primary }) => {
  const [open,setOpen]=useState(false);
  return (
    <div style={{ position:"relative",flexShrink:0 }}>
      {open&&<div style={{ position:"fixed",inset:0,zIndex:99 }} onClick={()=>setOpen(false)}/>}
      <button onClick={()=>setOpen(o=>!o)} style={{ background:"rgba(255,255,255,.2)",border:"none",cursor:"pointer",padding:8,borderRadius:10,display:"flex",...buttonStyle }}>
        <Icon name="cog" color={iconColor} size={20}/>
      </button>
      {open&&(
        <div style={{ position:"absolute",right:0,top:"calc(100% + 8px)",background:C.surface,borderRadius:14,boxShadow:"0 8px 32px rgba(0,0,0,.18)",padding:6,minWidth:180,zIndex:100,border:`1px solid ${C.border}` }}>
          {items.map((item,i)=>item==="divider"?(
            <div key={i} style={{ height:1,background:C.border,margin:"4px 8px" }}/>
          ):item.isFileInput?(
            // File upload item: use a <label> wrapping a real <input type="file">
            // This is the only approach that works in sandboxed iframes
            <label key={i} onChange={e=>{ setOpen(false); item.onFileChange(e); }}
              style={{ width:"100%",display:"flex",alignItems:"center",gap:10,padding:"10px 14px",cursor:"pointer",borderRadius:8,color:C.textPrimary,fontFamily:"'Roboto',sans-serif",fontSize:16,boxSizing:"border-box" }}>
              {item.icon&&<span style={{ display:"flex",alignItems:"center" }}>{item.icon}</span>}
              {item.label}
              <input type="file" accept="image/*" style={{ display:"none" }}/>
            </label>
          ):(
            <button key={i} onPointerDown={()=>{ setOpen(false); item.onClick(); }} style={{ width:"100%",border:"none",background:"none",padding:"10px 14px",cursor:"pointer",display:"flex",alignItems:"center",gap:10,borderRadius:8,color:item.danger?C.red:C.textPrimary,fontFamily:"'Roboto',sans-serif",fontSize:16 }}>
              {item.icon&&<span style={{ display:"flex",alignItems:"center" }}>{item.icon}</span>}
              {item.label}
            </button>
          ))}
        </div>
      )}
    </div>
  );
};

// mode: "default" (yes=green,no=red), "invert" (yes=red,no=green), "neutral" (yes=blue,no=green)
const YesNo = ({ value, onChange, invertColors=false, neutralColors=false }) => {
  const yc = neutralColors ? C.blue  : invertColors ? C.red   : C.green;
  const nc = neutralColors ? C.green : invertColors ? C.green : C.red;
  const btn=(lbl,val,ac)=>(
    <button onClick={()=>onChange(value===val?"":val)} style={{ flex:1,border:`1.5px solid ${value===val?ac:C.border}`,borderRadius:9,padding:"10px 0",background:value===val?`rgba(${hexToRgb(ac)},.15)`:"#fff",color:value===val?ac:C.textMuted,fontFamily:"'Roboto',sans-serif",fontWeight:700,fontSize:16,cursor:"pointer",transition:"all .15s" }}>{lbl}</button>
  );
  return <div style={{ display:"flex",gap:8 }}>{btn("Yes","yes",yc)}{btn("No","no",nc)}</div>;
};

const InspectionSummaryBar = ({ ins }) => {
  if(!ins) return null;
  const yn=v=>v==="yes"?"✓":v==="no"?"✗":"—";
  const cells=[
    {label:"Queen",   value:yn(ins.queen_seen),   color:ins.queen_seen==="yes"?C.green:ins.queen_seen==="no"?C.red:C.textPrimary},
    {label:"Eggs",    value:yn(ins.eggs_seen),     color:ins.eggs_seen==="yes"?C.green:ins.eggs_seen==="no"?C.red:C.textPrimary},
    {label:"Larvae",  value:yn(ins.larvae_seen),   color:ins.larvae_seen==="yes"?C.green:ins.larvae_seen==="no"?C.red:C.textPrimary},
    {label:"Capped",  value:yn(ins.capped_brood_seen), color:ins.capped_brood_seen==="yes"?C.green:ins.capped_brood_seen==="no"?C.red:C.textPrimary},
    {label:"Q Cells", value:ins.queen_cells==="yes"&&ins.queen_cell_action==="Left in Place"&&ins.queen_cells_left?`✓ (${ins.queen_cells_left})`:yn(ins.queen_cells),   color:ins.queen_cells==="yes"?C.red:ins.queen_cells==="no"?C.green:C.textPrimary},
    {label:"Brood Fr",value:ins.frames_brood==="Other"?(ins.frames_brood_custom||"?"):ins.frames_brood||"—",color:C.textPrimary},
    {label:"Store Fr",value:ins.frames_stores==="Other"?(ins.frames_stores_custom||"?"):ins.frames_stores||"—",color:C.textPrimary},
    {label:"Temp",    value:ins.temperament?ins.temperament+"/5":"—",color:C.textPrimary},
    {label:"Weight",  value:ins.weight_kg?ins.weight_kg+"kg":"—",color:C.textPrimary},
  ];
  return (
    <Card style={{ marginBottom:14,background:`rgba(${hexToRgb(C.primary)},.04)`,border:`1.5px solid rgba(${hexToRgb(C.primary)},.2)` }}>
      {ins.weightOnly?(
        <div style={{ display:"flex",justifyContent:"space-between",alignItems:"center" }}>
          <div>
            <div style={{ fontWeight:700,color:C.accent,fontSize:15 }}>Last Weight Log</div>
            <div style={{ fontSize:13,color:C.textMuted,marginTop:2 }}>No inspection data (winter log)</div>
          </div>
          <div style={{ textAlign:"right" }}>
            <div style={{ fontSize:22,fontWeight:700,color:C.accent }}>{ins.weight_kg} kg</div>
            <div style={{ fontSize:13,color:C.textMuted }}>{fmtDate(ins.date)}</div>
          </div>
        </div>
      ):(
      <div>
      <div style={{ display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:10 }}>
        <div style={{ fontWeight:700,color:C.primary,fontSize:15 }}>Last Inspection</div>
        <div style={{ display:"flex",alignItems:"center",gap:8 }}>
          <InspectionBadges ins={ins}/>
          <div style={{ fontSize:13,color:C.textMuted }}>{fmtDate(ins.date)}</div>
        </div>
      </div>
      <div style={{ display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:6 }}>
        {cells.map(c=>(
          <div key={c.label} style={{ background:"#fff",borderRadius:8,padding:"7px 8px",border:`1px solid ${C.border}` }}>
            <div style={{ fontSize:11,color:C.textMuted,textTransform:"uppercase",letterSpacing:0.8,fontWeight:700 }}>{c.label}</div>
            <div style={{ fontSize:15,fontWeight:700,color:c.color||C.textPrimary,marginTop:2 }}>{c.value}</div>
          </div>
        ))}
      </div>
      {ins.notes&&<div style={{ marginTop:10,paddingTop:10,borderTop:`1px solid ${C.border}`,fontSize:14,color:C.textSecondary,fontStyle:"italic",lineHeight:1.5 }}>{ins.notes.slice(0,120)}{ins.notes.length>120?"...":""}</div>}
      {(()=>{
        const acts=(ins.actions||[]).filter(a=>a.type);
        if(!acts.length) return null;
        return (
          <div style={{ marginTop:10,borderRadius:8,background:`rgba(${hexToRgb(C.accent)},.10)`,border:`1px solid rgba(${hexToRgb(C.accent)},.25)`,padding:"8px 12px" }}>
            <div style={{ fontSize:12,color:C.accent,fontWeight:700,textTransform:"uppercase",letterSpacing:0.8,marginBottom:4 }}>Actions</div>
            {acts.map((a,i)=>(
              <div key={i} style={{ fontSize:14,color:C.accent,lineHeight:1.5 }}>• {a.type}{a.qty&&a.qty!=="1"?` ×${a.qty}`:""}{a.details?` — ${a.details}`:""}</div>
            ))}
          </div>
        );
      })()}
      </div>
      )}
    </Card>
  );
};

// ── Apiary Setup (first-run + add new) ────────────────────────────────────
const ApiarySetup = ({ onComplete, isAdding=false, onCancel, allApiaries=[], onRestoreBackup }) => {
  const [form,setForm]=useState(()=>{
    const usedColors=allApiaries.map(a=>a.color).filter(Boolean);
    return {id:uid(),name:"",location:"",notes:"",beebase_id:"",color:nextColor(usedColors)};
  });
  const set=(k,v)=>setForm(f=>({...f,[k]:v}));
  const doSave=()=>{
    if(!form.name.trim()){alert("Please enter an apiary name");return;}
    if(!form.location.trim()){alert("Please enter a location");return;}
    onComplete({...form});
  };

  // ── Restore-from-backup (first-run only) ──
  const [restoring,setRestoring]=useState(false);
  const [restoreError,setRestoreError]=useState("");
  const [restorePreview,setRestorePreview]=useState(null);

  const handleRestoreFile = e => {
    const file=e.target.files?.[0];
    if(!file) return;
    setRestoring(true);
    setRestoreError("");
    setRestorePreview(null);
    const reader=new FileReader();
    reader.onload=ev=>{
      try{
        const data=JSON.parse(ev.target.result);
        if(!data.hives||!data.apiaries) throw new Error("Invalid BeeMark backup file — missing hives or apiaries data.");
        setRestorePreview(data);
      }catch(err){
        setRestoreError("error: "+err.message);
      }
      setRestoring(false);
    };
    reader.onerror=()=>{ setRestoreError("error: Could not read file"); setRestoring(false); };
    reader.readAsText(file);
    e.target.value="";
  };

  const doRestore = () => {
    if(!restorePreview) return;
    onRestoreBackup(restorePreview);
  };

  const previewActiveHives   = restorePreview?.hives?.filter(h=>h.status!=="Archived") || [];
  const previewArchivedHives = restorePreview?.hives?.filter(h=>h.status==="Archived")  || [];

  return (
    <div style={{ minHeight:"100vh",display:"flex",flexDirection:"column",justifyContent:"center",padding:24,background:`linear-gradient(160deg,${C.primaryLight} 0%,${C.bg} 50%,${C.surface} 100%)` }}>
      <HexBg opacity={0.06}/>
      <div style={{ position:"relative",zIndex:1,maxWidth:420,margin:"0 auto",width:"100%" }}>
        {!isAdding?(
          <div style={{ textAlign:"center",marginBottom:isAdding?32:24,display:"flex",flexDirection:"column",alignItems:"center" }}>
            <img src={LOGO_B64} alt="BeeMark" style={{ width:200,maxWidth:"80%",marginBottom:20,display:"block",marginLeft:"auto",marginRight:"auto" }}/>
            <div style={{ fontSize:17,color:C.textSecondary,lineHeight:1.6 }}>Set up your first apiary to get started.</div>
          </div>
        ):(
          <div style={{ textAlign:"center",marginBottom:32,display:"flex",flexDirection:"column",alignItems:"center" }}>
            <img src={LOGO_B64} alt="BeeMark" style={{ width:120,maxWidth:"60%",marginBottom:16,display:"block",marginLeft:"auto",marginRight:"auto" }}/>
            <div style={{ fontSize:22,fontWeight:700,color:C.textPrimary }}>Add New Apiary</div>
            <div style={{ fontSize:15,color:C.textMuted,marginTop:4 }}>Create a new apiary location.</div>
          </div>
        )}

        {!isAdding&&!restorePreview&&(
          <Card style={{ marginBottom:16,background:"rgba(255,255,255,.92)" }}>
            <label style={{ display:"block" }}>
              <div style={{ width:"100%",background:`linear-gradient(135deg,${C.accent},#1565C0)`,color:"#fff",borderRadius:10,padding:"13px 22px",cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",gap:6,fontFamily:"'Roboto',sans-serif",fontWeight:600,fontSize:16,boxSizing:"border-box" }}>
                <Icon name="restore" color="#fff" size={17}/> {restoring?"Reading file...":"Already a user? Upload Backup File"}
              </div>
              <input type="file" accept=".json" onChange={handleRestoreFile} style={{ display:"none" }}/>
            </label>
            {restoreError&&(
              <div style={{ marginTop:10,padding:"10px 14px",background:`rgba(${hexToRgb(C.red)},.08)`,border:`1.5px solid ${C.red}`,borderRadius:10,fontSize:14,color:C.red }}>
                {restoreError}
              </div>
            )}
            <div style={{ display:"flex",alignItems:"center",gap:10,margin:"14px 0" }}>
              <div style={{ flex:1,height:1,background:C.border }}/>
              <div style={{ fontSize:13,color:C.textMuted,fontWeight:700,letterSpacing:0.5 }}>OR</div>
              <div style={{ flex:1,height:1,background:C.border }}/>
            </div>
            <div style={{ textAlign:"center",fontSize:15,color:C.textSecondary,lineHeight:1.5 }}>New user? Create your first apiary below.</div>
          </Card>
        )}

        {!isAdding&&restorePreview&&(
          <Card style={{ marginBottom:16,background:"rgba(255,255,255,.92)" }}>
            <div style={{ fontWeight:700,color:C.textPrimary,fontSize:17,marginBottom:10 }}>Confirm Restore</div>
            <div style={{ fontSize:14,color:C.textSecondary,marginBottom:10,lineHeight:1.6 }}>This backup contains:</div>
            <div style={{ display:"grid",gridTemplateColumns:"1fr 1fr 1fr",gap:6,marginBottom:14 }}>
              {[
                {label:"Active Hives",   value:previewActiveHives.length,    color:C.primary},
                {label:"Archived Hives", value:previewArchivedHives.length,   color:C.textMuted},
                {label:"Apiaries",       value:restorePreview.apiaries?.length||0, color:C.accent},
                {label:"Inspections",    value:(restorePreview._summary?.inspections??restorePreview.hives?.reduce((s,h)=>s+h.inspections.length,0)), color:C.orange},
                {label:"Treatments",     value:(restorePreview._summary?.treatments??restorePreview.hives?.reduce((s,h)=>s+h.treatments.length,0)), color:C.blue},
                {label:"Actions",        value:(restorePreview._summary?.actions??restorePreview.hives?.reduce((s,h)=>s+(h.interventions||[]).length,0)), color:C.green},
              ].map(s=>(
                <div key={s.label} style={{ background:C.bg,borderRadius:8,padding:"8px 6px",textAlign:"center",border:`1px solid ${C.border}` }}>
                  <div style={{ fontSize:11,color:C.textMuted,textTransform:"uppercase",letterSpacing:0.6,fontWeight:700,marginBottom:2 }}>{s.label}</div>
                  <div style={{ fontSize:18,fontWeight:700,color:s.color }}>{s.value}</div>
                </div>
              ))}
            </div>
            {restorePreview.exportedAt&&(
              <div style={{ fontSize:13,color:C.textMuted,marginBottom:12 }}>
                Exported: {new Date(restorePreview.exportedAt).toLocaleDateString("en-GB",{day:"numeric",month:"short",year:"numeric",hour:"2-digit",minute:"2-digit"})}
              </div>
            )}
            <div style={{ display:"flex",gap:10 }}>
              <Btn onClick={()=>setRestorePreview(null)} variant="ghost" style={{ flex:1,justifyContent:"center" }}>Cancel</Btn>
              <Btn onClick={doRestore} style={{ flex:1,justifyContent:"center" }}>
                <Icon name="restore" size={15} color="#fff"/> Confirm Restore
              </Btn>
            </div>
          </Card>
        )}

        {!restorePreview&&(
          <>
            <Card style={{ marginBottom:16,background:"rgba(255,255,255,.92)" }}>
              <div style={{ fontWeight:700,color:C.textPrimary,marginBottom:16,fontSize:17 }}>Apiary Details</div>
              <Field label="Apiary Name *"><Input value={form.name} onChange={v=>set("name",v)} placeholder="e.g. Meadow Apiary"/></Field>
              <Field label="Location *"><Input value={form.location} onChange={v=>set("location",v)} placeholder="e.g. Back Garden"/></Field>
              <Field label="BeeBase Apiary ID"><Input value={form.beebase_id||""} onChange={v=>set("beebase_id",v)} placeholder="e.g. GB-1234567"/></Field>
              <Field label="Notes" style={{ marginBottom:0 }}>
                <textarea value={form.notes} onChange={e=>set("notes",e.target.value)} placeholder="Any notes about the site..." style={{...inputBase,minHeight:70,resize:"vertical"}}/>
              </Field>
            </Card>
            <div style={{ display:"flex",gap:10 }}>
              {isAdding&&<Btn onClick={onCancel} variant="ghost" style={{ flex:1,justifyContent:"center" }}>Cancel</Btn>}
              <Btn onClick={doSave} style={{ flex:1,justifyContent:"center",padding:15 }}>
                <Icon name="check" size={18} color="#fff"/> {isAdding?"Save Apiary":"Create Apiary"}
              </Btn>
            </div>
          </>
        )}
      </div>
    </div>
  );
};

// Palette for auto-assigning colours to new hives/apiaries
const COLOR_PALETTE = ["#2DBD8F","#3B9EE8","#E53935","#F57C00","#8E24AA","#00897B","#43A047","#0288D1","#E91E63","#FF6F00","#1565C0","#558B2F"];
// Hive colour tags support an additional yellow option (not used for apiaries)
const HIVE_COLOR_PALETTE = [...COLOR_PALETTE, "#FDD835"];
const nextColor = (usedColors, palette=COLOR_PALETTE) => {
  const used = new Set(usedColors);
  const unused=palette.find(c=>!used.has(c)); if(unused) return unused; return palette[usedColors.length%palette.length]||palette[0];
};

