// ── Apiary Detail (tapped from list) ─────────────────────────────────────
const ApiaryDetail = ({ apiary, hives, onEdit, onDelete, onBack, onSaveNotes, onNavigate }) => {
  const [deleteModal,setDeleteModal]=useState(false);
  const [editingNotes,setEditingNotes]=useState(false);
  const [notesVal,setNotesVal]=useState(apiary.notes||"");
  const [imgSrc,setImgSrc]=useState(apiary.image||null);
  const apiaryColor=apiary.color||C.primary;
  const apiaryColorDark=apiary.color||C.primaryDark;
  const apiaryHives=hives.filter(h=>h.apiaryId===apiary.id);
  const activeHives=apiaryHives.filter(h=>h.status!=="Archived");
  const allIns=apiaryHives.flatMap(h=>h.inspections);
  const lastIns=allIns.length?allIns.reduce((a,b)=>new Date(a.date)>new Date(b.date)?a:b):null;

  const handleImageUpload = e => {
    const file=e.target.files?.[0]; if(!file) return;
    const reader=new FileReader();
    reader.onload=ev=>{ const s=ev.target.result; setImgSrc(s); onSaveNotes({...apiary,image:s}); };
    reader.readAsDataURL(file);
  };

  const cogItems = [
    { label:"Edit Apiary", icon:<Icon name="edit" color={C.textSecondary} size={16}/>, onClick:onEdit },
    { label:imgSrc?"Change Photo":"Add Photo", icon:<Icon name="edit" color={C.textSecondary} size={16}/>,
      isFileInput:true, onFileChange:handleImageUpload },
    "divider",
    { label:"Delete Apiary", icon:<Icon name="trash" color={C.red} size={16}/>, danger:true, onClick:()=>setDeleteModal(true) },
  ];

  return (
    <PageWrap>
      {deleteModal&&<ConfirmModal title={`Delete ${apiary.name}?`} message="This will permanently delete this apiary and ALL hives within it. This cannot be undone." confirmLabel="Delete Apiary" confirmColor={C.red} onConfirm={()=>{ onDelete(apiary.id); }} onCancel={()=>setDeleteModal(false)}/>}


      {/* Hero bar — uses apiary colour, optionally shows uploaded image */}
      <div style={{ position:"relative",background:imgSrc?`url(${imgSrc}) center/cover`:`linear-gradient(135deg,${apiaryColor},${apiaryColorDark})`,minHeight:100,padding:"16px 16px 18px" }}>
        {imgSrc&&<div style={{ position:"absolute",inset:0,background:"rgba(0,0,0,.38)",borderRadius:0,pointerEvents:"none" }}/>}
        <div style={{ position:"relative",zIndex:1,display:"flex",alignItems:"center",gap:10 }}>
          <button onClick={onBack} style={{ background:"rgba(255,255,255,.2)",border:"none",cursor:"pointer",padding:6,borderRadius:10,display:"flex",flexShrink:0 }}><Icon name="back" color="#fff" size={22}/></button>
          <div style={{ flex:1 }}>
            <div style={{ fontSize:22,fontWeight:700,color:"#fff",lineHeight:1.2 }}>{apiary.name}</div>
            <div style={{ fontSize:14,color:"rgba(255,255,255,.85)",marginTop:2,display:"flex",alignItems:"center",gap:4 }}>
              <Icon name="location" color="rgba(255,255,255,.85)" size={12}/>{apiary.location}
            </div>
          </div>
          <CogMenu items={cogItems} iconColor="#fff"/>
        </div>
      </div>

      <div style={{ padding:16 }}>
        {/* Summary tiles — active hives only */}
        {(() => {
          const totalSupers = activeHives.reduce((s,h)=>s+Number(h.supers||0),0);
          const tiles = [
            {label:"Hives",         value:activeHives.length,                   color:apiaryColor},
            {label:"Total Supers",  value:totalSupers,                          color:C.primary},
            {label:"Last Inspected",value:lastIns?fmtDate(lastIns.date):"None", color:C.orange},
          ];
          return (
            <div style={{ display:"grid",gridTemplateColumns:"1fr 1fr 1fr",gap:10,marginBottom:14 }}>
              {tiles.map(s=>(
                <Card key={s.label} style={{ padding:"14px 12px" }}>
                  <div style={{ fontSize:12,color:C.textMuted,textTransform:"uppercase",letterSpacing:0.8,fontWeight:700,marginBottom:4 }}>{s.label}</div>
                  <div style={{ fontSize:18,fontWeight:700,color:s.color,lineHeight:1.2 }}>{String(s.value)}</div>
                </Card>
              ))}
            </div>
          );
        })()}

        {/* Details card */}
        <Card style={{ marginBottom:14 }}>
          <div style={{ fontWeight:700,color:C.textPrimary,marginBottom:12,fontSize:15 }}>Apiary Details</div>
          {[{label:"Name",value:apiary.name},{label:"Location",value:apiary.location},{label:"BeeBase ID",value:apiary.beebase_id||"—"}].map(f=>(
            <div key={f.label} style={{ marginBottom:10 }}>
              <div style={{ fontSize:12,color:C.textMuted,textTransform:"uppercase",letterSpacing:0.8,fontWeight:600 }}>{f.label}</div>
              <div style={{ fontSize:16,color:C.textPrimary,fontWeight:500,marginTop:2 }}>{f.value}</div>
            </div>
          ))}
        </Card>

        {/* Notes — always visible, inline editable */}
        <Card style={{ marginBottom:14 }}>
          <div style={{ display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:10 }}>
            <div style={{ fontWeight:700,color:C.textPrimary,fontSize:15 }}>Notes</div>
            <button onClick={()=>{ if(editingNotes){ onSaveNotes({...apiary,notes:notesVal}); } setEditingNotes(e=>!e); }}
              style={{ background:"none",border:"none",cursor:"pointer",fontSize:14,color:C.primary,fontFamily:"'Roboto',sans-serif",fontWeight:600,padding:"4px 0" }}>
              {editingNotes?"Save":"Edit"}
            </button>
          </div>
          {editingNotes?(
            <textarea value={notesVal} onChange={e=>setNotesVal(e.target.value)}
              placeholder="Add notes about this apiary..."
              style={{...inputBase,minHeight:100,resize:"vertical"}}/>
          ):(
            <div style={{ fontSize:16,color:notesVal?C.textPrimary:C.textMuted,lineHeight:1.65,fontStyle:notesVal?"normal":"italic" }}>
              {notesVal||"No notes yet. Tap Edit to add notes."}
            </div>
          )}
        </Card>

        {/* Active hive list — tappable */}
        {activeHives.length>0&&(()=>{
          const HiveRow=({h,i,total})=>{
            const sc=STATUS_COLORS[h.status]||null;
            return (
              <div onClick={()=>onNavigate("hive-detail",{hiveId:h.id})}
                style={{ display:"flex",alignItems:"center",gap:10,padding:"10px 16px",cursor:"pointer",background:"#fff",borderTop:i>0?`1px solid ${C.border}`:"none",transition:"background .15s" }}
                onMouseEnter={e=>e.currentTarget.style.background=C.surfaceAlt}
                onMouseLeave={e=>e.currentTarget.style.background="#fff"}>
                <div style={{ width:4,alignSelf:"stretch",borderRadius:2,background:h.color||C.primary,flexShrink:0,minHeight:36 }}/>
                <div style={{ flex:1 }}>
                  <div style={{ fontWeight:600,color:C.textPrimary,fontSize:15 }}>{h.name}</div>
                  <div style={{ fontSize:13,color:C.textMuted }}>{hiveTypeLabel(h)}</div>
                </div>
                {sc&&<Chip label={h.status} color={sc} small/>}
                <Icon name="chevron" color={C.textMuted} size={16} style={{ transform:"rotate(-90deg)" }}/>
              </div>
            );
          };
          return (
            <Card style={{ padding:0,overflow:"hidden",marginBottom:14 }}>
              <div style={{ fontWeight:700,color:C.textPrimary,fontSize:15,padding:"14px 16px 10px" }}>
                Hives in this Apiary
              </div>
              {activeHives.map((h,i)=><HiveRow key={h.id} h={h} i={i} total={activeHives.length}/>)}
            </Card>
          );
        })()}

        {/* Archived hives — collapsible section */}
        {(()=>{
          const archivedHives=apiaryHives.filter(h=>h.status==="Archived");
          if(archivedHives.length===0) return null;
          return <ArchivedHivesSection hives={archivedHives} onNavigate={onNavigate}/>;
        })()}
      </div>
    </PageWrap>
  );
};

