const DataTransfer = ({ hives, apiaries, activeApiaryId, equipManual, onImport, onBack }) => {
  const [importStatus,setImportStatus]=useState("");
  const [importPreview,setImportPreview]=useState(null); // parsed data preview before confirm
  const [importing,setImporting]=useState(false);
  const [confirmImport,setConfirmImport]=useState(false);
  const [exportStatus,setExportStatus]=useState(""); // "","saving","saved","error"

  // Counts for display
  const activeHives   = hives.filter(h=>h.status!=="Archived");
  const archivedHives = hives.filter(h=>h.status==="Archived");
  const totalInspections = hives.reduce((s,h)=>s+h.inspections.length,0);
  const totalTreatments  = hives.reduce((s,h)=>s+h.treatments.length,0);
  const totalActions     = hives.reduce((s,h)=>s+(h.interventions||[]).length,0);

  const buildExportData = () => ({
    version: APP_VERSION,
    exportedAt: new Date().toISOString(),
    hives,
    apiaries,
    activeApiaryId,
    equipManual,
    _summary: {
      activeHives:   activeHives.length,
      archivedHives: archivedHives.length,
      apiaries:      apiaries.length,
      inspections:   totalInspections,
      treatments:    totalTreatments,
      actions:       totalActions,
    },
  });

  const handleExport = async () => {
    const json = JSON.stringify(buildExportData(), null, 2);
    const filename = `beemark-backup-${new Date().toISOString().slice(0,10)}.json`;
    const isNative = !!(window.Capacitor?.isNativePlatform?.());
    if(isNative) {
      // Android: write directly to the Downloads folder via Capacitor Filesystem
      setExportStatus("saving");
      try {
        await Filesystem.writeFile({
          path: `Download/${filename}`,
          data: json,
          directory: Directory.ExternalStorage,
          encoding: Encoding.UTF8,
          recursive: false,
        });
        setExportStatus("saved");
        setTimeout(()=>setExportStatus(""),4000);
      } catch(err) {
        console.error("Export failed:", err);
        setExportStatus("error");
        setTimeout(()=>setExportStatus(""),5000);
      }
    } else {
      // Web: standard blob download
      const blob = new Blob([json], {type:"application/json"});
      const url  = URL.createObjectURL(blob);
      const a    = document.createElement("a");
      a.href = url;
      a.download = filename;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
      setExportStatus("saved");
      setTimeout(()=>setExportStatus(""),3000);
    }
  };

  const handleFileRead = e => {
    const file = e.target.files?.[0];
    if(!file) return;
    setImporting(true);
    setImportStatus("");
    setImportPreview(null);
    const reader = new FileReader();
    reader.onload = ev => {
      try {
        const data = JSON.parse(ev.target.result);
        if(!data.hives || !data.apiaries) throw new Error("Invalid BeeMark backup file — missing hives or apiaries data.");
        // Show preview; user must confirm before we overwrite
        setImportPreview(data);
        setConfirmImport(true);
      } catch(err) {
        setImportStatus("error: " + err.message);
      }
      setImporting(false);
    };
    reader.onerror = () => { setImportStatus("error: Could not read file"); setImporting(false); };
    reader.readAsText(file);
    e.target.value="";
  };

  const doImport = () => {
    if(!importPreview) return;
    onImport(importPreview);
    setImportPreview(null);
    setConfirmImport(false);
    setImportStatus("success");
  };

  const previewActiveHives   = importPreview?.hives?.filter(h=>h.status!=="Archived") || [];
  const previewArchivedHives = importPreview?.hives?.filter(h=>h.status==="Archived")  || [];

  return (
    <PageWrap>
      <PageHeader title="Import / Export" onBack={onBack}/>
      <div style={{ padding:16 }}>

        {/* ── Export ── */}
        <Card style={{ marginBottom:14 }}>
          <div style={{ fontWeight:700,color:C.textPrimary,fontSize:17,marginBottom:6 }}>Export Data</div>
          <div style={{ fontSize:15,color:C.textSecondary,lineHeight:1.6,marginBottom:14 }}>
            Creates a complete backup of all your data — hives, apiaries, all inspection logs, treatments, actions, notes, equipment counts and settings. Import this file on any device to fully restore your BeeMark data.
          </div>

          {/* Current data summary */}
          <div style={{ display:"grid",gridTemplateColumns:"1fr 1fr 1fr",gap:8,marginBottom:14 }}>
            {[
              {label:"Active Hives",   value:activeHives.length,   color:C.primary},
              {label:"Archived Hives", value:archivedHives.length,  color:C.textMuted},
              {label:"Apiaries",       value:apiaries.length,       color:C.accent},
              {label:"Inspections",    value:totalInspections,      color:C.orange},
              {label:"Treatments",     value:totalTreatments,       color:C.blue},
              {label:"Actions",        value:totalActions,          color:C.green},
            ].map(s=>(
              <div key={s.label} style={{ background:C.bg,borderRadius:8,padding:"10px 8px",textAlign:"center" }}>
                <div style={{ fontSize:11,color:C.textMuted,textTransform:"uppercase",letterSpacing:0.7,fontWeight:700,marginBottom:3 }}>{s.label}</div>
                <div style={{ fontSize:20,fontWeight:700,color:s.color }}>{s.value}</div>
              </div>
            ))}
          </div>
          <Btn onClick={handleExport} disabled={exportStatus==="saving"} style={{ width:"100%",justifyContent:"center",opacity:exportStatus==="saving"?0.7:1 }}>
            <Icon name="check" size={17} color="#fff"/>
            {exportStatus==="saving"?"Saving...":"Export Backup"}
          </Btn>
          {exportStatus==="saved"&&(
            <div style={{ marginTop:10,padding:"10px 14px",background:`rgba(${hexToRgb(C.primary)},.1)`,border:`1.5px solid ${C.primary}`,borderRadius:10,fontSize:14,color:C.primaryDark,fontWeight:600 }}>
              ✓ Backup saved to your Downloads folder
            </div>
          )}
          {exportStatus==="error"&&(
            <div style={{ marginTop:10,padding:"10px 14px",background:`rgba(${hexToRgb(C.red)},.08)`,border:`1.5px solid ${C.red}`,borderRadius:10,fontSize:14,color:C.red,fontWeight:600 }}>
              Export failed — please check app storage permissions in Android Settings
            </div>
          )}
        </Card>

        {/* ── Import ── */}
        <Card style={{ marginBottom:14 }}>
          <div style={{ fontWeight:700,color:C.textPrimary,fontSize:17,marginBottom:6 }}>Import Data</div>
          <div style={{ fontSize:15,color:C.textSecondary,lineHeight:1.6,marginBottom:14 }}>
            Load a BeeMark backup file. You will see a summary of what will be imported before anything is changed.
            {" "}<strong style={{ color:C.red }}>This replaces all current data.</strong> Export first if needed.
          </div>

          {/* Import status */}
          {importStatus==="success"&&(
            <div style={{ background:`rgba(${hexToRgb(C.green)},.1)`,border:`1px solid ${C.green}`,borderRadius:10,padding:"10px 14px",marginBottom:12,fontSize:15,fontWeight:600,color:C.green }}>
              ✓ Data imported successfully — all records restored.
            </div>
          )}
          {importStatus.startsWith("error")&&(
            <div style={{ background:`rgba(${hexToRgb(C.red)},.08)`,border:`1px solid ${C.red}`,borderRadius:10,padding:"10px 14px",marginBottom:12,fontSize:15,color:C.red }}>
              {importStatus}
            </div>
          )}

          {/* Confirm import dialog */}
          {confirmImport&&importPreview&&(
            <div style={{ background:`rgba(${hexToRgb(C.orange)},.06)`,border:`1.5px solid rgba(${hexToRgb(C.orange)},.3)`,borderRadius:12,padding:14,marginBottom:14 }}>
              <div style={{ fontWeight:700,color:C.textPrimary,fontSize:15,marginBottom:10 }}>Confirm Import</div>
              <div style={{ fontSize:14,color:C.textSecondary,marginBottom:10,lineHeight:1.6 }}>
                This backup contains:
              </div>
              <div style={{ display:"grid",gridTemplateColumns:"1fr 1fr 1fr",gap:6,marginBottom:14 }}>
                {[
                  {label:"Active Hives",   value:previewActiveHives.length,    color:C.primary},
                  {label:"Archived Hives", value:previewArchivedHives.length,   color:C.textMuted},
                  {label:"Apiaries",       value:importPreview.apiaries?.length||0, color:C.accent},
                  {label:"Inspections",    value:(importPreview._summary?.inspections??importPreview.hives?.reduce((s,h)=>s+h.inspections.length,0)), color:C.orange},
                  {label:"Treatments",     value:(importPreview._summary?.treatments??importPreview.hives?.reduce((s,h)=>s+h.treatments.length,0)), color:C.blue},
                  {label:"Actions",        value:(importPreview._summary?.actions??importPreview.hives?.reduce((s,h)=>s+(h.interventions||[]).length,0)), color:C.green},
                ].map(s=>(
                  <div key={s.label} style={{ background:"#fff",borderRadius:8,padding:"8px 6px",textAlign:"center",border:`1px solid ${C.border}` }}>
                    <div style={{ fontSize:11,color:C.textMuted,textTransform:"uppercase",letterSpacing:0.6,fontWeight:700,marginBottom:2 }}>{s.label}</div>
                    <div style={{ fontSize:18,fontWeight:700,color:s.color }}>{s.value}</div>
                  </div>
                ))}
              </div>
              {importPreview.exportedAt&&(
                <div style={{ fontSize:13,color:C.textMuted,marginBottom:12 }}>
                  Exported: {new Date(importPreview.exportedAt).toLocaleDateString("en-GB",{day:"numeric",month:"short",year:"numeric",hour:"2-digit",minute:"2-digit"})}
                </div>
              )}
              <div style={{ display:"flex",gap:10 }}>
                <Btn onClick={()=>{ setConfirmImport(false); setImportPreview(null); }} variant="ghost" style={{ flex:1,justifyContent:"center" }}>Cancel</Btn>
                <Btn onClick={doImport} variant="danger" style={{ flex:1,justifyContent:"center" }}>
                  <Icon name="restore" size={15} color={C.red}/> Confirm Import
                </Btn>
              </div>
            </div>
          )}

          {!confirmImport&&(
            <label style={{ display:"block" }}>
              <div style={{ width:"100%",background:`linear-gradient(135deg,${C.red},#c62828)`,color:"#fff",borderRadius:10,padding:"13px 22px",cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",gap:6,fontFamily:"'Roboto',sans-serif",fontWeight:500,fontSize:16,boxSizing:"border-box" }}>
                <Icon name="restore" color="#fff" size={17}/> {importing?"Reading file...":"Choose Backup File"}
              </div>
              <input type="file" accept=".json" onChange={handleFileRead} style={{ display:"none" }}/>
            </label>
          )}
        </Card>

        <Card>
          <div style={{ fontSize:14,color:C.textMuted,lineHeight:1.7 }}>
            <strong>What's included in a backup:</strong> all hives (active + archived), all apiaries, every inspection log, treatment record, action log, notes, equipment inventory totals and app settings. A full restore brings everything back exactly as it was.
          </div>
        </Card>
      </div>
    </PageWrap>
  );
};

// ── Info Hub (top-level Info page with menu items) ─────────────────────────
